    lat: 16.5631, lon: -94.9633, elevationM: 40,
    reliefContext: "The low-elevation gap at the Isthmus of Tehuantepec — the narrowest and lowest crossing between the Sierra Madre de Chiapas and the Sierra Madre de Oaxaca.",
